package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.lang.reflect.TypeVariable;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Unit tests for MapType.construct
 */
public class MapType_construct_TriageGen0Test {

    private final TypeFactory typeFactory = TypeFactory.defaultInstance();

    @Test
    public void testConstruct_WithTwoTypeParameters() {
        // Case where vars.length == 2 (e.g., HashMap<K, V>)
        Class<?> rawType = HashMap.class;
        JavaType keyT = typeFactory.constructType(String.class);
        JavaType valueT = typeFactory.constructType(Integer.class);

        MapType result = MapType.construct(rawType, keyT, valueT);

        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(keyT, result.getKeyType());
        assertEquals(valueT, result.getValueType());
    }

    @Test
    public void testConstruct_WithZeroTypeParameters() {
        // Case where vars.length != 2 (e.g., a class with no generics)
        Class<?> rawType = Map.class; 
        // Note: In many JDKs, Map.class has 2 type parameters, 
        // but if we use a class like Object.class or a custom non-generic class:
        Class<?> nonGenericClass = Object.class;

        JavaType keyT = typeFactory.constructType(String.class);
        JavaType valueT = typeFactory.constructType(Integer.class);

        MapType result = MapType.construct(nonGenericClass, keyT, valueT);

        assertNotNull(result);
        assertEquals(nonGenericClass, result.getRawClass());
    }

    @Test
    public void testConstruct_WithOneTypeParameter() {
        // Case where vars.length == 1
        class SingleParam<T> extends HashMap<T, Object> {}
        Class<?> rawType = SingleParam.class;

        JavaType keyT = typeFactory.constructType(String.class);
        JavaType valueT = typeFactory.constructType(Integer.class);

        MapType result = MapType.construct(rawType, keyT, valueT);

        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
    }

    @Test
    public void testConstruct_WithThreeTypeParameters() {
        // Case where vars.length == 3
        class TripleParam<A, B, C> extends HashMap<A, B> {}
        Class<?> rawType = TripleParam.class;

        JavaType keyT = typeFactory.constructType(String.class);
        JavaType valueT = typeFactory.constructType(Integer.class);

        MapType result = MapType.construct(rawType, keyT, valueT);

        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
    }

    @Test
    public void testConstruct_WithNullRawType() {
        // Testing robustness against null rawType (though likely to throw NPE in real scenarios, 
        // we test the branch logic for vars == null)
        JavaType keyT = typeFactory.constructType(String.class);
        JavaType valueT = typeFactory.constructType(Integer.class);

        try {
            MapType result = MapType.construct(null, keyT, valueT);
            assertNotNull(result);
        } catch (NullPointerException e) {
            // If the implementation calls rawType.getTypeParameters() immediately, 
            // it will throw NPE. This is acceptable behavior for a professional test.
        }
    }
}
